<section class="admin-panel" aria-labelledby="primary-navigation-title"><header class="admin-panel__header"><div class="admin-panel__heading"><h2 class="admin-panel__title" id="primary-navigation-title">Primary Navigation</h2><p class="admin-panel__description">Manage the Webcore primary menu hierarchy and targets.</p></div><a class="admin-button admin-button--primary" href="<?= htmlspecialchars($itemPath('/create'), ENT_QUOTES, 'UTF-8') ?>">Add item</a></header><div class="admin-panel__body"><?php if ($items === []): ?><div class="admin-empty-state"><h3 class="admin-empty-state__title">No navigation items yet</h3><p class="admin-empty-state__description">Add the first Primary Navigation item.</p></div><?php else: ?><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th scope="col">Item</th><th scope="col">Target</th><th scope="col">Visibility</th><th scope="col">Actions</th></tr></thead><tbody><?php foreach ($items as $item): $actions=$reorderActions[$item->id()]??[]; ?><tr><td><strong class="admin-table-primary"><?= str_repeat('— ', $item->parentId()===null?0:1) . htmlspecialchars($item->label(), ENT_QUOTES, 'UTF-8') ?></strong></td><td class="admin-table-meta"><?= htmlspecialchars($item->targetKind() === 'custom' ? (string) $item->customUrl() : $item->targetKind() . ':' . (string) $item->targetReference(), ENT_QUOTES, 'UTF-8') ?></td><td><?= $item->isVisible() ? 'Visible' : 'Hidden' ?></td><td><?php foreach(['up'=>'Move up','down'=>'Move down'] as $direction=>$label): if(isset($actions[$direction])): ?><form class="admin-inline-form" method="post" action="<?= htmlspecialchars($itemPath('/reorder'), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="_token" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="parent_id" value="<?= htmlspecialchars((string)$actions[$direction]['parent_id'], ENT_QUOTES, 'UTF-8') ?>"><?php foreach($actions[$direction]['item_ids'] as $sibling): ?><input type="hidden" name="item_ids[]" value="<?= $sibling ?>"><?php endforeach; ?><button class="admin-button admin-button--link" type="submit"><?= $label ?></button></form><?php endif; endforeach; ?><a class="admin-button admin-button--link" href="<?= htmlspecialchars($itemPath('/' . $item->id() . '/edit'), ENT_QUOTES, 'UTF-8') ?>">Edit</a><form class="admin-inline-form" method="post" action="<?= htmlspecialchars($itemPath('/' . $item->id() . '/delete'), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="_token" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><button class="admin-button admin-button--link admin-action-danger" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></section>
